import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.Bx6eOp9J.js";const h=JSON.parse('{"title":"2026-10-30 Agent Research and Competitor Intelligence","description":"Completion and recording evidence, recovery ownership, extension lifecycle and delivery/license boundaries.","frontmatter":{"title":"2026-10-30 Agent Research and Competitor Intelligence","description":"Completion and recording evidence, recovery ownership, extension lifecycle and delivery/license boundaries."},"headers":[],"relativePath":"en/runtime/daily-intelligence/2026-10-30.md","filePath":"en/runtime/daily-intelligence/2026-10-30.md","lastUpdated":1793326549000}'),i={name:"en/runtime/daily-intelligence/2026-10-30.md"};function s(o,e,d,c,l,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="_2026-10-30-agent-research-and-competitor-intelligence" tabindex="-1">2026-10-30 Agent Research and Competitor Intelligence <a class="header-anchor" href="#_2026-10-30-agent-research-and-competitor-intelligence" aria-label="Permalink to &quot;2026-10-30 Agent Research and Competitor Intelligence&quot;">​</a></h1><p>The main conclusion is that <strong>recovery, success, completeness and authority require separate evidence</strong>. Codex/Claude separate human decisions, restored permissions and execution states; Paperclip and ADK repair completion/persistence boundaries; Eigent exposes healthy-looking connections that lose work. Aegis claim corrections, MCP&#39;s Final extension lifecycle and Paradev&#39;s pending license proposal also matter. All CodeFlowMu/FCoP implications are <strong>pending validation leads</strong>.</p><h2 id="_1-aegis-withdraws-old-benchmark-claims-and-unreliable-endorsements" tabindex="-1">1. Aegis withdraws old benchmark claims and unreliable endorsements <a class="header-anchor" href="#_1-aegis-withdraws-old-benchmark-claims-and-unreliable-endorsements" aria-label="Permalink to &quot;1. Aegis withdraws old benchmark claims and unreliable endorsements&quot;">​</a></h2><p><strong>Status: COMMITTED; CLAIM CORRECTION, NOT A NEW EXPERIMENT</strong></p><p>Commit de9f7b3 in Justin0504/Aegis explicitly says the live homepage still carried withdrawn 99.9% / 1.06 ms ToolGuard-Bench figures and other pages presented the v1 cascade as current. Source pages are corrected and the peer-reviewed claim is removed. The author also discloses that most testimonial names were invented and the one real endorser was a co-author; the module is removed. This records the author&#39;s disclosure and changes, not independent validation of replacement metrics or the marketing deployment.</p><p>Pending FCoP lead: paper, source and live claims need a shared versioned evidence boundary. Useful discussion: how to mark old links, retain correction history and provide independent reproduction.</p><p>Original sources: <a href="https://github.com/Justin0504/Aegis/commit/de9f7b3c4d3c41905e0e7767b7ffa778eb52109d" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_2-codex-0-166-0-releases-permission-preserving-resume-and-executor-packaging" tabindex="-1">2. Codex 0.166.0 releases permission-preserving resume and executor packaging <a class="header-anchor" href="#_2-codex-0-166-0-releases-permission-preserving-resume-and-executor-packaging" aria-label="Permalink to &quot;2. Codex 0.166.0 releases permission-preserving resume and executor packaging&quot;">​</a></h2><p><strong>Status: RELEASED</strong></p><p>The stable release explicitly lists preserved acknowledged approval/permission settings across resume and fork, codex queue --resume, descendant restoration when unarchiving a parent, reconnection and startup/shutdown race fixes, and the standalone executor in canonical CLI/app-server packages. It adds doctor --network-only and GPT-6.1 Terra catalog entries. Only listed release scope is confirmed; later main changes are not automatically included.</p><p>Pending CodeFlowMu lead: resume must preserve acknowledged permissions and child relationships, not just messages. Discuss old-state migration, executor version negotiation and permission-restoration failures.</p><p>Original sources: <a href="https://github.com/openai/codex/releases/tag/rust-v0.166.0" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_3-codex-main-separates-fresh-human-decisions-and-recording-completeness" tabindex="-1">3. Codex main separates fresh human decisions and recording completeness <a class="header-anchor" href="#_3-codex-main-separates-fresh-human-decisions-and-recording-completeness" aria-label="Permalink to &quot;3. Codex main separates fresh human decisions and recording completeness&quot;">​</a></h2><p><strong>Status: MERGED #58045/#58040/#58166/#58172/#58189/#58182; RELEASE INCLUSION NOT VERIFIED</strong></p><p>#58045 adds managed prompt-user rules requiring a fresh one-time human decision, overriding saved allowances, hook allows and automatic review. A capable client must exist and only eligible recipients can answer. #58040 retains original tool-call identity and encrypted-argument evidence. #58166/#58172 separate recording_complete from task outcome: enabled recorder initialization failure blocks startup, first write failure persists, and a valid final newline-terminated record is required; valid prefixes remain incomplete. #58189 freezes search permissions for the active turn. #58182 adds managed permissions.network, rejects mixed spellings and warns policy publishers to preserve reader compatibility.</p><p>These PRs are merged, but inclusion in 0.166 is not inferred from timing. Pending FCoP lead: human decision, authorization observation, execution result and complete recording are distinct facts. Discuss reconnect prompt replay, last-writer release and partial-trace verification contracts.</p><p>Original sources: <a href="https://github.com/openai/codex/pull/58045" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/openai/codex/pull/58040" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/openai/codex/pull/58166" target="_blank" rel="noreferrer">Evidence 3</a> · <a href="https://github.com/openai/codex/pull/58172" target="_blank" rel="noreferrer">Evidence 4</a> · <a href="https://github.com/openai/codex/pull/58189" target="_blank" rel="noreferrer">Evidence 5</a> · <a href="https://github.com/openai/codex/pull/58182" target="_blank" rel="noreferrer">Evidence 6</a></p><h2 id="_4-claude-code-2-1-314-tightens-write-boundaries-resumed-sandboxes-and-execution-evidence" tabindex="-1">4. Claude Code 2.1.314 tightens write boundaries, resumed sandboxes and execution evidence <a class="header-anchor" href="#_4-claude-code-2-1-314-tightens-write-boundaries-resumed-sandboxes-and-execution-evidence" aria-label="Permalink to &quot;4. Claude Code 2.1.314 tightens write boundaries, resumed sandboxes and execution evidence&quot;">​</a></h2><p><strong>Status: RELEASED</strong></p><p>blockWritesOutsideWorkingDirectories is added for Write/Edit/NotebookEdit, rejecting outside-working-directory paths in every permission mode. The release fixes sandbox protection after worktree resume/continue, expired remote-policy refresh behavior, excluded setting sources still contributing rules/consents, and Monitor shell commands bypassing Bash hooks. Blocked or unexecuted shell/MCP calls no longer appear executed; stopping a command tells the model it may already have run. Startup failure in claude -p now prints an error and exits 1.</p><p>The new file-tool switch is not a guarantee over all shell writes. Pending lead: jointly verify restored permissions, hook coverage and uncertain side effects. Discuss no-verdict/blocked/cancelled/executed states and Monitor hooks that may block or ask but cannot approve or rewrite.</p><p>Original sources: <a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.314" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_5-mcp-sep-3392-is-final-directory-based-extension-maturity" tabindex="-1">5. MCP SEP-3392 is Final: directory-based extension maturity <a class="header-anchor" href="#_5-mcp-sep-3392-is-final-directory-based-extension-maturity" aria-label="Permalink to &quot;5. MCP SEP-3392 is Final: directory-based extension maturity&quot;">​</a></h2><p><strong>Status: MERGED #3392; FINAL PROCESS SEP</strong></p><p>The final file defines Experimental to Beta to Stable or Core using <code>specification/&lt;stage&gt;/</code> directories. One repository can contain several stages; the old PR opening&#39;s repository-renaming design is superseded. Beta and Stable entry each require an Extensions Track SEP; Stable behavior is fixed within a core protocol revision, and Core promotion requires a Standards Track SEP. Apps/Auth are classified Stable, Skills/Tasks/Server Card Beta. This is process only, not changed wire negotiation. Extensions remain disabled by default with explicit opt-in; repository moves and SDK delivery require separate checks.</p><p>Pending lead: track protocol revision, extension maturity, SDK implementation and actual enablement separately. Discuss moved links, Beta revisions sharing identifiers, and real-use/conformance evidence for stabilization.</p><p>Original sources: <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3392" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/blob/84d84572/seps/3392-extension-lifecycle.md" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_6-paperclip-preserves-rejected-completion-and-requires-json-publication-evidence" tabindex="-1">6. Paperclip preserves rejected completion and requires JSON publication evidence <a class="header-anchor" href="#_6-paperclip-preserves-rejected-completion-and-requires-json-publication-evidence" aria-label="Permalink to &quot;6. Paperclip preserves rejected completion and requires JSON publication evidence&quot;">​</a></h2><p><strong>Status: MERGED #18227/#18228; RELEASE NOT VERIFIED</strong></p><p>#18227 fixes a rejected declared finish call being overwritten by synthetic done when the provider turn ends. The rejection is turn-scoped and restorable; an uncorrected rejection becomes a nonrecoverable failure without success evidence, a review request or automatic missing-result recovery. #18228 applies the existing file-publication gate to explicit Write/Publish result.json requests: a summary document cannot replace an attachment or accessible work product. Input files, inline discussion and negated requests retain their boundaries.</p><p>High learning value and high competitive risk; increase completion-verification weight on the main radar. Pending FCoP lead: provider termination is not controller acceptance and a summary is not file delivery. Discuss corrected reports, restored rejection state and output-request detection errors.</p><p>Original sources: <a href="https://github.com/paperclipai/paperclip/pull/18227" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/18228" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_7-paperclip-attributes-activity-to-runner-and-prevents-stale-task-panel-readiness" tabindex="-1">7. Paperclip attributes activity to Runner and prevents stale task-panel readiness <a class="header-anchor" href="#_7-paperclip-attributes-activity-to-runner-and-prevents-stale-task-panel-readiness" aria-label="Permalink to &quot;7. Paperclip attributes activity to Runner and prevents stale task-panel readiness&quot;">​</a></h2><p><strong>Status: MERGED #18050/#18131; RELEASE NOT VERIFIED</strong></p><p>An operation captures opaque Runner context before use and notifies after success. Context rotates on warm attachment/recovery; callers cannot choose a run ID, and current authority is checked before activity recording. Task panels map authorized history/live events by company/task/run/agent and installation version, then make at most three readiness attempts instead of periodic polling. Helper success only means pipe publication; full queues or write failure can drop hints. Hints grant no access and their loss does not mean the operation failed.</p><p>High learning value and competitive risk; increase plugin-governance/visibility attention. Pending lead: a long-lived provider must not attribute work to an old run, and UI readiness does not prove current-task use. Discuss context rotation, lost hints and authorized history recovery.</p><p>Original sources: <a href="https://github.com/paperclipai/paperclip/pull/18050" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/18131" target="_blank" rel="noreferrer">Evidence 2</a></p><h2 id="_8-paperclip-preserves-blocked-workspaces-and-warm-policy-and-schedules-committed-deadlines" tabindex="-1">8. Paperclip preserves blocked workspaces and warm policy, and schedules committed deadlines <a class="header-anchor" href="#_8-paperclip-preserves-blocked-workspaces-and-warm-policy-and-schedules-committed-deadlines" aria-label="Permalink to &quot;8. Paperclip preserves blocked workspaces and warm policy, and schedules committed deadlines&quot;">​</a></h2><p><strong>Status: MERGED #17839/#18169/#17840; RELEASE NOT VERIFIED</strong></p><p>#17839 registers an exactly bound source-workspace preservation obligation before a blocked-restart transaction commits, without creating replacement execution. #18169 persists resource disposition so recovery does not stop a successful warm Runner just because copy-back metadata is absent. Connection refresh grants no new execution, and failed/cancelled runs still stop. #17840 removes idle heartbeat wakes for the routine worker, using saved deadlines and committed producer changes while retaining overdue work after capped catch-up. It does not make the whole system polling-free.</p><p>High learning value and competitive risk; increase recovery/scheduling maturity weight. Pending lead: retention, execution authority and next wake are separate obligations. Upstream scoped checks are not fleet cost or deployment proof. Discuss pause/resume, drain and rollback without losing overdue work.</p><p>Original sources: <a href="https://github.com/paperclipai/paperclip/pull/17839" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/18169" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/paperclipai/paperclip/pull/17840" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_9-eigent-merges-single-window-ownership-and-missed-delivery-recovery-1-0-7-is-not-yet-released" tabindex="-1">9. Eigent merges single-window ownership and missed-delivery recovery; 1.0.7 is not yet released <a class="header-anchor" href="#_9-eigent-merges-single-window-ownership-and-missed-delivery-recovery-1-0-7-is-not-yet-released" aria-label="Permalink to &quot;9. Eigent merges single-window ownership and missed-delivery recovery; 1.0.7 is not yet released&quot;">​</a></h2><p><strong>Status: MERGED #2131/#2140/#2142; LATEST RELEASE STILL v1.0.6</strong></p><p>#2131 assigns one background-work owner to avoid duplicate starts across tabs. Web Locks absence or lock rejection retains the old fallback, so this is not universal exactly-once. #2140 gives every websocket a new session ID, preventing delayed old cleanup from removing a new registration; missing pongs reconnect, Run now queues directly, subscribe/30-second recovery checks pending executions from the last 10 minutes, execution IDs deduplicate, and a queue preserves simultaneous events. #2142 only prepares version 1.0.7; latest published Release remains 1.0.6.</p><p>High learning value, medium-high risk; increase scheduling/multiwindow maturity attention on the main radar. Pending lead: socket health is not deliverability and requested is not started. Discuss work beyond the ten-minute window, owner loss and server registration cleanup.</p><p>Original sources: <a href="https://github.com/eigent-ai/eigent/pull/2131" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/eigent-ai/eigent/pull/2140" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/eigent-ai/eigent/pull/2142" target="_blank" rel="noreferrer">Evidence 3</a> · <a href="https://github.com/eigent-ai/eigent/releases/tag/v1.0.6" target="_blank" rel="noreferrer">Evidence 4</a></p><h2 id="_10-superset-paradev-releases-2-0-2-per-turn-undo-has-separate-experimental-gates" tabindex="-1">10. Superset/Paradev releases 2.0.2; per-turn Undo has separate experimental gates <a class="header-anchor" href="#_10-superset-paradev-releases-2-0-2-per-turn-undo-has-separate-experimental-gates" aria-label="Permalink to &quot;10. Superset/Paradev releases 2.0.2; per-turn Undo has separate experimental gates&quot;">​</a></h2><p><strong>Status: desktop-v2.0.2 / cli-v2.0.2 RELEASED; #8941 MERGED, INCLUSION NOT VERIFIED</strong></p><p>Desktop 2.0.2 explicitly lists PR actions using the viewer&#39;s GitHub identity, advancing prior merged work to release; CLI 2.0.2 is also published. Separately, #8941 merges per-turn snapshots/Undo. Tool-call cards can stand alone; snapshots/Undo are off by default and gated by acp-chat/experimental settings. Undo restores files only, retains chat, hash-checks files and rejects moved HEAD, another active chat or shared-worktree turns. Release inclusion of this PR is not inferred from timestamps.</p><p>High learning value and risk; increase identity/recovery attention on the main radar. Pending lead: visible diffs, recoverable snapshots and safe Undo are different capabilities. Discuss shell-edit coverage, concurrent writers and partial rollback failures.</p><p>Original sources: <a href="https://github.com/ParadevAI/Paradev/releases/tag/desktop-v2.0.2" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/ParadevAI/Paradev/releases/tag/cli-v2.0.2" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/ParadevAI/Paradev/pull/8941" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_11-paradev-devs-separates-a-machine-free-main-session-from-delegated-tasks" tabindex="-1">11. Paradev Devs separates a machine-free main session from delegated tasks <a class="header-anchor" href="#_11-paradev-devs-separates-a-machine-free-main-session-from-delegated-tasks" aria-label="Permalink to &quot;11. Paradev Devs separates a machine-free main session from delegated tasks&quot;">​</a></h2><p><strong>Status: #9030/#9031 MERGED AND LISTED IN desktop-v2.0.2; CHANNELS GATED; #9116 MERGED LATER</strong></p><p>A Dev&#39;s main session replies, remembers and delegates without a machine or direct subagents. Task sessions have separate cloud workspaces, a three-task concurrency cap and dedupe keys. A minute-based reconciler finds undelivered messages, wedged workflows and lost turns, redelivers within bounded windows and exposes retries. Release notes list #9030/#9031, but upstream says channels has no production users; this is not production maturity. Later #9116 makes delegated work ordinary Paradev tasks shared by writer/reviewer; inclusion in that release is unverified.</p><p>High learning value and risk; increase digital-employee/company-model weight. Pending lead: communication identity, work facts and execution resources can be separated; unlimited provider retries still need operational controls. Discuss redelivery, task-state ownership and cross-layer authority.</p><p>Original sources: <a href="https://github.com/ParadevAI/Paradev/pull/9030" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9031" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9116" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_12-paradev-merges-organization-plugin-governance-mit-relicensing-remains-draft" tabindex="-1">12. Paradev merges organization-plugin governance; MIT relicensing remains draft <a class="header-anchor" href="#_12-paradev-merges-organization-plugin-governance-mit-relicensing-remains-draft" aria-label="Permalink to &quot;12. Paradev merges organization-plugin governance; MIT relicensing remains draft&quot;">​</a></h2><p><strong>Status: #8327 MERGED, RELEASE NOT VERIFIED; #9107 OPEN/DRAFT; MAIN LICENSE REMAINS ELv2</strong></p><p>Organization plugins sync using the adding admin&#39;s GitHub identity, enforce role access across catalog/install/bundle/MCP proxy/cloud workspace, reject same-version changed content and remove installs on organization exit/sign-out. Private-address and DNS connection targets are guarded. Sync is add-source/manual only, with opt-in compatibility for clients. Separately, #9107 proposes ELv2 to MIT but is explicitly draft/do-not-merge pending founder confirmation. Main LICENSE.md remains ELv2; current licensing is not changed by the draft.</p><p>High learning value, medium-high risk; increase plugin trust attention. Add a pending structural license change to the radar while keeping current classification unchanged. Pending lead: bind sync identity to content versions. Discuss admin revocation, existing-install access and version boundaries of an eventual license change. This records repository status only.</p><p>Original sources: <a href="https://github.com/ParadevAI/Paradev/pull/8327" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9107" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/ParadevAI/Paradev/blob/main/LICENSE.md" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_13-orca-main-protects-unattended-input-and-preserves-precise-kill-evidence" tabindex="-1">13. Orca main protects unattended input and preserves precise kill evidence <a class="header-anchor" href="#_13-orca-main-protects-unattended-input-and-preserves-precise-kill-evidence" aria-label="Permalink to &quot;13. Orca main protects unattended input and preserves precise kill evidence&quot;">​</a></h2><p><strong>Status: MERGED #36133/#36142/#36020; DESKTOP RELEASE NOT VERIFIED</strong></p><p>#36133 suppresses supported CLI startup updaters for unattended desktop/paired launches so prepared input is not consumed by update dialogs; it does not edit global settings or persist overrides into resume commands. #36142 encodes precise kill-delivered evidence compatibly with 1.4.244 readers without claiming observed exit. #36020 makes macOS read-back mismatch fail, marks unchanged actions unverified/suspected_noop and bounds AX calls. A new CLI on an old runtime retains old behavior, and writing to the wrong unlabeled field remains open.</p><p>High learning value, medium-high risk; retain second-circle priority for unattended work, delivery and computer use. Pending lead: stop requested, kill delivered and process exited differ; call success is not effect verification. Discuss host/CLI generations, legitimate unchanged actions and maintenance windows for suppressed updates.</p><p>Original sources: <a href="https://github.com/stablyai/orca/pull/36133" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/stablyai/orca/pull/36142" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/stablyai/orca/pull/36020" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_14-openhands-rechecks-directory-containment-and-repairs-loop-detection-and-lan-opt-in" tabindex="-1">14. OpenHands rechecks directory containment and repairs loop detection and LAN opt-in <a class="header-anchor" href="#_14-openhands-rechecks-directory-containment-and-repairs-loop-detection-and-lan-opt-in" aria-label="Permalink to &quot;14. OpenHands rechecks directory containment and repairs loop detection and LAN opt-in&quot;">​</a></h2><p><strong>Status: MERGED #6316/#6278/#18363; LATEST SDK RELEASE STILL 1.59.0</strong></p><p>SDK #6316 rechecks containment after appending directory index.html, closing a symlink escape. It requires a session key/cookie; upstream calls severity low and leaves check/open race hardening for follow-up. #6278 identifies repeated validation errors by locations/types rather than changing thought text, counts one parallel response as one attempt and allows incremental field repairs. Main-project #18363 restores explicit LAN session-key opt-in and corrects occupied-port/backend-only diagnostics; without opt-in key suppression remains. Release inclusion is unverified for all three.</p><p>Pending lead: derived directory paths need authorization, stuck detection must allow genuine progress, and LAN enablement is not authentication. Discuss symlink TOCTOU, parallel-error grouping and cross-platform launcher evidence. Upstream reproductions are not local results.</p><p>Original sources: <a href="https://github.com/OpenHands/software-agent-sdk/pull/6316" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6278" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/OpenHands/OpenHands/pull/18363" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_15-google-adk-waits-for-event-persistence-before-retry-and-tightens-rewind-identity-boundaries" tabindex="-1">15. Google ADK waits for event persistence before retry and tightens rewind/identity boundaries <a class="header-anchor" href="#_15-google-adk-waits-for-event-persistence-before-retry-and-tightens-rewind-identity-boundaries" aria-label="Permalink to &quot;15. Google ADK waits for event persistence before retry and tightens rewind/identity boundaries&quot;">​</a></h2><p><strong>Status: COMMITTED ON MAIN; RELEASE NOT VERIFIED</strong></p><p>3b74a99 adds an event-queue barrier before node retry so sibling outputs are appended to session before rescan, preventing duplicate side effects from missed evidence. dfd534a preserves create_session state untouched by undone events; an overwritten initial value without original history is still cleared, not fully reconstructed. ec9756e rejects path-breaking Firestore app/user/session IDs; old invalid IDs can no longer be read/deleted through the service. 9688feb filters thought=True parts from MCP results and progress.</p><p>Pending FCoP lead: emitted events are not persisted events, recovery precision is bounded by original evidence, and identities must not be blindly concatenated into paths. Discuss barrier cancellation failures, invalid-ID migration and initial-state rollback evidence.</p><p>Original sources: <a href="https://github.com/google/adk-python/commit/3b74a99bd0e4e405fadd712e7253af2b0dcbe25d" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/google/adk-python/commit/dfd534a8802a1f03beaae90f90d29892b28a6918" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/google/adk-python/commit/ec9756eaed517d89fde20e5f514b798edb532854" target="_blank" rel="noreferrer">Evidence 3</a> · <a href="https://github.com/google/adk-python/commit/9688feb5ce88f761420e50c03963a881d009d671" target="_blank" rel="noreferrer">Evidence 4</a></p><h2 id="_16-beads-connects-retained-type-protection-to-routine-cleanup" tabindex="-1">16. Beads connects retained-type protection to routine cleanup <a class="header-anchor" href="#_16-beads-connects-retained-type-protection-to-routine-cleanup" aria-label="Permalink to &quot;16. Beads connects retained-type protection to routine cleanup&quot;">​</a></h2><p><strong>Status: MERGED #7932; RELEASE NOT VERIFIED</strong></p><p>Building on yesterday&#39;s permanent tombstones, types.retained holds specified closed-row types back from routine prune/purge/sweep, gc decay, admin cleanup and a specific doctor cleanup. Only retain-ids sweep deletes and retires their IDs. The setting is database-only and read failure prevents deletion. A client facing an old server without the behavior token reads the setting and refuses a plain sweep when retained types exist. Explicit delete/sql and other named paths are excluded; protection is per row, not graph-wide.</p><p>High learning value, medium risk; retain main-radar attention with stronger cleanup/idempotency focus. Pending lead: a safe path is insufficient if routine deletion bypasses it. Discuss old client/server combinations, graph retention and auditing explicit deletion.</p><p>Original sources: <a href="https://github.com/gastownhall/beads/pull/7932" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_17-agentlas-os-1-2-71-scopes-path-bearing-memories-to-their-project" tabindex="-1">17. Agentlas OS 1.2.71 scopes path-bearing memories to their project <a class="header-anchor" href="#_17-agentlas-os-1-2-71-scopes-path-bearing-memories-to-their-project" aria-label="Permalink to &quot;17. Agentlas OS 1.2.71 scopes path-bearing memories to their project&quot;">​</a></h2><p><strong>Status: RELEASED</strong></p><p>Curator ruleset 1.4.0 treats lessons containing project paths as project-specific so unrelated projects do not recall them. Detection covers quotes, backticks, brackets, positions after colon/equal/comma and C:/ paths; a root preceded by word characters in a URL fragment remains excluded. This is a scoped heuristic repair, not proof of full cross-user isolation.</p><p>Medium-high learning value, medium risk; increase second-circle memory-scope attention. Pending CodeFlowMu lead: portable lessons and project facts need different recall boundaries. Discuss sensitive path-free memories, project relocation and reclassification of old memories.</p><p>Original sources: <a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/v1.2.71" target="_blank" rel="noreferrer">Evidence 1</a></p><h2 id="_18-crewai-documents-an-earlier-breaking-change-and-preserves-work-on-repetition-stops" tabindex="-1">18. CrewAI documents an earlier breaking change and preserves work on repetition stops <a class="header-anchor" href="#_18-crewai-documents-an-earlier-breaking-change-and-preserves-work-on-repetition-stops" aria-label="Permalink to &quot;18. CrewAI documents an earlier breaking change and preserves work on repetition stops&quot;">​</a></h2><p><strong>Status: 1.15.33 RELEASED; #8710/#8706 MERGED; INDIVIDUAL RELEASE INCLUSION NOT ASSUMED</strong></p><p>#8710 corrects missing migration/breaking-change documentation for CrewAgentExecutor and old import paths removed in 1.15.29; the removal is historical, while its documentation correction is new. #8706 warns then forces a final answer for repeated identical tool/args/result calls while retaining work. Raise policy may still throw, text/native thresholds differ and alternating A/B loops remain out of scope. Published 1.15.33 separately lists unrestorable checkpoint callbacks saved as null, compatibility imports and token-usage fixes; not all main changes are assumed included.</p><p>Pending lead: migration documentation is part of recovery contracts and loop termination should retain useful work. Discuss visible failure-policy states, partial checkpoint restoration and whether forced final answers satisfy completion gates.</p><p>Original sources: <a href="https://github.com/crewAIInc/crewAI/pull/8710" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/crewAIInc/crewAI/pull/8706" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.33" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="_19-langfuse-and-phoenix-release-attribution-usage-and-redaction-changes" tabindex="-1">19. Langfuse and Phoenix release attribution, usage and redaction changes <a class="header-anchor" href="#_19-langfuse-and-phoenix-release-attribution-usage-and-redaction-changes" aria-label="Permalink to &quot;19. Langfuse and Phoenix release attribution, usage and redaction changes&quot;">​</a></h2><p><strong>Status: Langfuse 4.72.0 / Phoenix 20.27.0 RELEASED</strong></p><p>Langfuse 4.72.0 attributes AI Gateway spans to the actual gateway API key/service instead of the temporary ingestion token used for project batches, fixes cache-write TTL double counting and adds trace-level evaluator filters. Phoenix 20.27.0 explicitly includes earlier #15828 subagent/credential protection and new #17343 exported-log/span PII redaction. The new facts are release/engineering changes; analytics and redaction labels are not complete governance proof.</p><p>Pending FCoP lead: observability must preserve actual caller attribution without leaking credentials or PII. Discuss mixed-key batches, rejection of unattributable spans and verifiability before/after export redaction.</p><p>Original sources: <a href="https://github.com/langfuse/langfuse/releases/tag/v4.72.0" target="_blank" rel="noreferrer">Evidence 1</a> · <a href="https://github.com/langfuse/langfuse/pull/19398" target="_blank" rel="noreferrer">Evidence 2</a> · <a href="https://github.com/Arize-ai/phoenix/releases/tag/arize-phoenix-v20.27.0" target="_blank" rel="noreferrer">Evidence 3</a></p><h2 id="cross-project-signals-and-classification" tabindex="-1">Cross-project signals and classification <a class="header-anchor" href="#cross-project-signals-and-classification" aria-label="Permalink to &quot;Cross-project signals and classification&quot;">​</a></h2><ul><li><strong>Facts are not substitutes:</strong> task success is not recording completeness; provider termination is not controller acceptance; Stop or delivered kill is not observed exit; socket health is not deliverability.</li><li><strong>Recovery preserves owners and evidence:</strong> Codex fresh human decisions, Paperclip activity/warm policy, Eigent window ownership and the ADK event barrier must not lose authority or evidence of existing effects.</li><li><strong>Version and maturity remain separate:</strong> MCP Final is process adoption, not universal SDK implementation. Paradev feature flags, Eigent&#39;s version bump versus published Release, and Orca CLI/runtime generations are separately tracked.</li><li><strong>Corrections matter:</strong> Aegis claim withdrawal, CrewAI&#39;s historical breaking-change correction and observability attribution/redaction changes materially affect engineering decisions.</li></ul><p>Classification: 19 information groups and pending validation leads. Upstream experiments, tests and deployments retain their original scope and are not local results. Local engineering experiments: 0; articles: 0; formal development reviews: 0; external comments/messages: 0. No Research Runtime business lifecycle, scheduler, candidate, scorecard or publication facts were changed.</p><h2 id="dual-source-checks-deduplication-and-coverage-gaps" tabindex="-1">Dual-source checks, deduplication and coverage gaps <a class="header-anchor" href="#dual-source-checks-deduplication-and-coverage-gaps" aria-label="Permalink to &quot;Dual-source checks, deduplication and coverage gaps&quot;">​</a></h2><p>Actual start: 2026-10-30 10:03:00 Asia/Shanghai. The main incremental window runs from the previous successful check start, 2026-10-29 12:47:01, to this start. Per-source checkpoints and published reports, including October 29, provide deduplication. Unfinished feeds retain older pending windows. Historical material is not presented as new today.</p><p>The current main Registry was first read through connected GitHub tools: 47 people, blob 8d97df65269aa2b4accd1366d1b71319f99c6efd. People/source relationships remain many-to-many. The six governance/verification subjects and their original boundaries remain; no separately reportable new code was confirmed in their related repositories. bulbasaur-skill-cli is not the official AGENTSAFE artifact. No new personal code was confirmed in the listed Yue Zhao repositories. New Issue #46 is a third-party Zambo/AER-1 curation suggestion, OPEN with no comments, not an accepted entry or a standard authored by Zhao. Unverified implementation/corpus claims remain follow-up leads, not research results.</p><p>GitHub coverage: 88 targets including 32 competitors; 684 incremental commit records across 25 changed targets. Default heads were separately read for 62 accessible zero-increment targets. There are 5342 raw PR/Issue records; dynamic-page unique_count is retained rather than treating every record as a distinct event. Releases are bounded. Important PRs were read in full; MCP&#39;s final file and Paradev&#39;s main LICENSE.md take precedence over stale PR prose. Superset retains its monitoring name and its redirect to ParadevAI/Paradev was verified with repository ID 1080370450. Event author/merger evidence is retained: Paperclip&#39;s cryppadotta/nickyleach/devinfoley and Paradev&#39;s saddlepaddle directly participated in merges; accounts are not mapped to unverified personal identities.</p><p>Explicit gaps: Codex, Claude Code and Orca PR/Issue feeds remain unfinished after 12 pages each. All three TSA feeds return 404; deletion/private status is not inferred. Releases are mainly latest ten, Codex latest three, not an exhaustive asset-edit history audit. Discussions, roadmaps and every architecture/license file were not exhaustively checked. Only completed successful source queries advance their watermark; partial, failed and unchecked are not no-change. No global full-coverage watermark is claimed.</p><p>Public social/author/official web checks are separate: the current 47 people were searched in 12 groups, with targeted X checks for Zhao and reliably identifiable accounts/projects, plus direct Cursor changelog/blog, Audit Commons and Paradev pages. No reliably timed new personal post inside the window was confirmed. Search misses are not exhaustive X coverage and unrelated names are not attributed. Cursor&#39;s visible latest changelog remains October 20; the visible October 27 Audit Commons material is historical. GitHub primary engineering evidence can stand independently; two GitHub links are not two source types.</p><h2 id="github-archive-and-website-delivery" tabindex="-1">GitHub archive and website delivery <a class="header-anchor" href="#github-archive-and-website-delivery" aria-label="Permalink to &quot;GitHub archive and website delivery&quot;">​</a></h2><p>Both languages retain the same 19 groups, states, 49 original sources and judgments. Only the two dated reports and two existing indexes are updated through connected GitHub tools, with unique descending dates and fixed entry points. Existing VitePress/gh-pages delivery preserves layout, public snapshots, translation caches and other published content. Current-main/publication concurrency checks, four-file readback, matching Pages success and actual bilingual live clicks are recorded separately in a local receipt; this paragraph does not preclaim deployment success.</p>',108)])])}const g=a(i,[["render",s]]);export{h as __pageData,g as default};
